// The Founders' Pact: the captain opens the keep's founding records once the keep knows the player well.
// The entry ships off, so the narrator can't tell the secret before the player has earned it.

// 1. Read the played character's Renown. Renown is a Blueprint stat, so the persona owns its own copy.
const renown = persona.stats.Renown.value;

// 2. Seventy is the top of Renown's "Known" band, where the keep asks favors of the name and owes them back.
//    From there the captain trusts the player with the charter. Below it the entry goes off again,
//    so a fall in standing closes the records.
const trusted = renown >= 70;

// 3. Write only on a change, so a quiet turn leaves the lorebook as it is.
//    The write spells out the whole path, so the editor can trace which entry it switches.
const pact = dictionaries.Emberwatch.entries["The Founders' Pact"];
if (pact.enabled !== trusted) {
  dictionaries.Emberwatch.entries["The Founders' Pact"].enabled = trusted;
}

